import json
from pathlib import Path

# Українська абетка для сортування за абеткою; решта символів — після неї за кодом
АБЕТКА = "абвгґдеєжзиіїйклмнопрстуфхцчшщьюя"


def ключ_абетки(рядок):
    return [(0, АБЕТКА.index(c)) if c in АБЕТКА else (1, ord(c)) for c in рядок.lower()]


def значення_рядок(значення):
    if isinstance(значення, str):
        return значення
    return json.dumps(значення, ensure_ascii=False)


def main():
    with open(Path("дані") / "конфіги.json", encoding="utf-8") as f:
        конфіги = json.load(f)

    def ланцюжок(імʼя):
        # Повертає список від кореня до конфігу або None, якщо є цикл
        шлях = []
        поточний = імʼя
        while поточний is not None and поточний in конфіги:
            if поточний in шлях:
                return None
            шлях.append(поточний)
            поточний = конфіги[поточний].get("успадковує")
